SELECT 'core-2026-09-v4','countable-uncountable','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"countable-uncountable","title":"Countable and uncountable nouns","level":"A1","order":14,"summary":"Choose quantity expressions and agreement from a noun’s meaning in context.","learningGoals":["Count the things or measure an amount","Asking about quantity","Some and individual units"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Count the things or measure an amount","explanation":"Countable nouns name separate units and can be plural. Uncountable nouns name amounts or collections in the senses used here. Other senses may differ.","examples":["three baskets","some equipment"]},{"title":"Asking about quantity","explanation":"Use how many before plural countable nouns and how much before uncountable nouns. Use plural agreement with the former and singular agreement with the latter.","examples":["How many baskets are ready?","How much equipment is available?"]},{"title":"Some and individual units","explanation":"Some works with both plural countable and uncountable nouns. For an uncountable noun, add a unit phrase when counting individual quantities.","examples":["some luggage","two pieces of luggage"]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-countable-uncountable"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Countability is a property of a noun’s meaning in context, not a judgement about whether real objects can physically be counted. Furniture refers to a collection as an uncountable concept; chairs names separate countable units. The choice affects articles, quantity words and verb agreement."],"rules":[{"title":"Count the things or measure an amount","explanation":"Countable nouns name separate units and can be plural. Uncountable nouns name amounts or collections in the senses used here. Other senses may differ.","examples":["three baskets","some equipment","The **information is** useful."],"pattern":"**a chair / two chairs** · **some furniture**","paragraphs":["A singular count noun usually needs a determiner such as a, this or my. A plural count noun can be used generally without one. An uncountable noun does not normally take a/an in its uncountable sense. Add a unit phrase when needed: a bottle of water."],"id":"countable-uncountable-foundation-1","domain":"noun-phrases","referenceIds":["bc-countable-uncountable"],"readingVersion":"foundations-2026-09-v2"},{"title":"Asking about quantity","explanation":"Use how many before plural countable nouns and how much before uncountable nouns. Use plural agreement with the former and singular agreement with the latter.","examples":["How many baskets are ready?","How much equipment is available?","There are **three pieces of equipment**."],"pattern":"**How many chairs?** / **How much furniture?**","paragraphs":["Use many with plural count nouns and much with uncountable nouns. A lot of works with both and is often more natural in affirmative everyday statements. Plural count nouns take plural agreement; uncountable subjects normally take singular agreement."],"id":"countable-uncountable-foundation-2","domain":"noun-phrases","referenceIds":["bc-countable-uncountable"],"readingVersion":"foundations-2026-09-v2"},{"title":"Some and individual units","explanation":"Some works with both plural countable and uncountable nouns. For an uncountable noun, add a unit phrase when counting individual quantities.","examples":["some luggage","two pieces of luggage","How **many** bags? How **much** luggage?"],"pattern":"**a piece of advice** / **some advice**","paragraphs":["Some works with plural counts and uncountable amounts. To count an uncountable quantity, identify an appropriate unit: two pieces of information, three slices of bread. The unit noun becomes plural while the uncountable noun remains unchanged."],"id":"countable-uncountable-foundation-3","domain":"noun-phrases","referenceIds":["bc-countable-uncountable"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"A noun may change countability with its sense. Chicken can mean an animal or meat; coffee can mean a substance or a serving; paper can mean a material or a newspaper/article. The exercises state the intended sense so that a valid alternate meaning is not unfairly marked wrong.","examples":["The **information is** useful.","There are **three pieces of equipment**.","How **many** bags? How **much** luggage?"],"id":"countable-uncountable-foundation-4","domain":"noun-phrases","referenceIds":["bc-countable-uncountable"],"readingVersion":"foundations-2026-09-v2"},{"domain":"noun-phrases","id":"countability-shifts","title":"When a noun changes between count and non-count uses","explanation":"Countability belongs to a noun’s use in context, not only its dictionary entry. A non-count substance can become a count serving or type; an abstract quality can become an instance. Some nouns change meaning: paper can mean a material, a newspaper or a scholarly article. Learn the associated determiners with each sense.","pattern":"**coffee** / **two coffees** · **experience** / **an experience**","examples":["We bought **glass** for the window. / She broke **a glass**.","He has **experience**. / It was **an unusual experience**."],"commonMistakes":["A change of meaning can license a count form; it does not make every uncountable noun freely plural. Ordinary information and advice remain non-count."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"noun-phrases","id":"partitives-and-measures","title":"Pieces, pairs, quantities and partitive expressions","explanation":"A partitive expression identifies a unit or amount of something. The unit noun can be counted and determines agreement in an ordinary unit-based phrase. Choose units appropriate to the substance or object. Some plural-only objects are counted with pair; containers can stand for their contents.","pattern":"a **piece of** advice · two **pairs of** scissors","examples":["**Two bottles of water are** on the table.","I need **a sheet of paper** and **a piece of equipment**."],"commonMistakes":["Do not add plural endings to the non-count noun just because the unit is plural: three pieces of furniture, not three furnitures."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**a chair / two chairs** · **some furniture**","**How many chairs?** / **How much furniture?**","**a piece of advice** / **some advice**"],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["present-continuous"],"readingReferenceIds":["bc-countable-uncountable","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='countable-uncountable'
